import React from 'react';

const navBarStyles = `
.custom-navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.07);
  z-index: 100;
  display: flex;
  align-items: center;
  height: 64px;
  padding: 0 32px;
}
.custom-navbar .navbar-brand {
  display: flex;
  align-items: center;
  margin-right: 32px;
  text-decoration: none;
}
.custom-navbar .logo {
  height: 40px;
  margin-right: 10px;
}
.custom-navbar .nav {
  display: flex;
  gap: 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.custom-navbar .nav-link {
  color: #222;
  text-decoration: none;
  font-weight: 500;
  padding: 8px 12px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
}
.custom-navbar .nav-link.active,
.custom-navbar .nav-link:hover {
  background: #f2f2f2;
  color: #002147;
}
.custom-navbar .dropdown {
  position: relative;
}
.custom-navbar .dropdown-menu {
  display: none;
  position: absolute;
  top: 110%;
  left: 0;
  background: #fff;
  min-width: 160px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  border-radius: 6px;
  z-index: 200;
  padding: 8px 0;
}
.custom-navbar .dropdown:hover .dropdown-menu {
  display: block;
}
.custom-navbar .dropdown-item {
  color: #222;
  padding: 8px 20px;
  text-decoration: none;
  display: block;
  transition: background 0.2s;
}
.custom-navbar .dropdown-item:hover {
  background: #f2f2f2;
}
.custom-navbar .langmenu,
.custom-navbar .usermenu-container {
  margin-left: 24px;
}
.custom-navbar .login a {
  color: #002147;
  font-weight: 600;
  text-decoration: none;
  padding: 8px 16px;
  border-radius: 4px;
  background: #f2f2f2;
  transition: background 0.2s;
}
.custom-navbar .login a:hover {
  background: #ffcc00;
  color: #222;
}
@media (max-width: 900px) {
  .custom-navbar {
    flex-direction: column;
    height: auto;
    padding: 8px;
  }
  .custom-navbar .nav {
    flex-direction: column;
    gap: 8px;
  }
}
`;

const NavBar = () => {
  React.useEffect(() => {
    if (!document.getElementById('custom-navbar-styles')) {
      const style = document.createElement('style');
      style.id = 'custom-navbar-styles';
      style.innerHTML = navBarStyles;
      document.head.appendChild(style);
    }
  }, []);

  return (
    <nav className="custom-navbar">
      <a href="https://eucenje.sum.ba/moodle/" className="navbar-brand">
        <img
          src="https://eucenje.sum.ba/moodle/pluginfile.php/1/core_admin/logocompact/300x300/1746443490/Logo%20sumarum.png"
          className="logo"
          alt="SUMARUM"
        />
      </a>
      <ul className="nav">
        <li>
          <a className="nav-link active" href="https://eucenje.sum.ba/moodle/">Naslovnica</a>
        </li>
        <li className="dropdown">
          <a className="nav-link dropdown-toggle" href="#">ISS</a>
          <div className="dropdown-menu">
            <a className="dropdown-item" href="https://studomat.sum.ba">Studenti</a>
            <a className="dropdown-item" href="https://is.sum.ba">Nastavnici</a>
          </div>
        </li>
      </ul>
      <div style={{ flex: 1 }} />
      <div className="langmenu">
        <div className="dropdown show">
          <a href="#" className="btn dropdown-toggle" aria-haspopup="true">
            <span className="langbutton">Hrvatski ‎(hr)‎</span>
          </a>
          <div className="dropdown-menu dropdown-menu-right">
            <a href="https://eucenje.sum.ba/moodle/?lang=en" className="dropdown-item" lang="en">
              English ‎(en)‎
            </a>
            <a href="#" className="dropdown-item" aria-current="true">
              Hrvatski ‎(hr)‎
            </a>
          </div>
        </div>
      </div>
      <div className="usermenu-container">
        <span className="login">
          <a href="https://eucenje.sum.ba/moodle/login/index.php">Prijava</a>
        </span>
      </div>
    </nav>
  );
};

export default NavBar;
